(()=>{'use strict';
const TZ='America/Sao_Paulo';
const app=document.querySelector('#app'), searchLayer=document.querySelector('#searchLayer'), authLayer=document.querySelector('#authLayer');
const state={user:null,theme:localStorage.getItem('aninexus:theme')||'dark',scheduleTimer:null,searchTimer:null,routeAbort:null,list:new Map(),catalogPage:1,catalogFilters:{search:'',genre:'',format:'',sort:'POPULAR'},season:null};
const ICON={
 home:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9"><path d="M3.5 10.8 12 3.7l8.5 7.1"/><path d="M5.7 9.8v10h12.6v-10M9.5 19.8v-6h5v6"/></svg>',
 grid:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/></svg>',
 calendar:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="5.5" width="17" height="15" rx="2"/><path d="M8 3.5v4M16 3.5v4M3.5 9.5h17"/></svg>',
 season:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 19c4.5-1 6.8-3.4 7-7.1C7.6 12 5.2 10.7 4 8.2c4.3-1.6 7.2-.6 8.8 3 1.2-3.7 3.7-5.8 7.2-6.2.2 5.2-2.2 8.2-7.1 9.1-.5 2.9-2.1 5-4.9 6.4"/></svg>',
 users:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M16 20v-1.4c0-2.4-2-4.4-4.4-4.4H7.4C5 14.2 3 16.2 3 18.6V20"/><circle cx="9.5" cy="7.4" r="3.4"/><path d="M15.7 4.2a3.4 3.4 0 0 1 0 6.5M18 14.4c1.9.8 3 2.4 3 4.2V20"/></svg>',
 search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="6.6"/><path d="m16 16 4.2 4.2"/></svg>',
 moon:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20.2 15.2A8.5 8.5 0 0 1 8.8 3.8 8.8 8.8 0 1 0 20.2 15.2Z"/></svg>',
 sun:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>',
 arrow:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M14 7l5 5-5 5"/></svg>',
 menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9"><path d="M4 7h16M4 12h16M4 17h16"/></svg>',
 close:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9"><path d="m6 6 12 12M18 6 6 18"/></svg>',
 heart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20.8 8.7c0 5-8.8 10.2-8.8 10.2S3.2 13.7 3.2 8.7A4.7 4.7 0 0 1 12 6.3a4.7 4.7 0 0 1 8.8 2.4Z"/></svg>',
 plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',
 play:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="5" width="17" height="14" rx="2.5"/><path d="m10 9.1 5 2.9-5 2.9V9.1Z"/></svg>',
 star:'<svg viewBox="0 0 24 24"><path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9L12 3Z"/></svg>',
 left:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m14.5 6-6 6 6 6"/></svg>',right:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m9.5 6 6 6-6 6"/></svg>',
 mic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="8" y="3" width="8" height="12" rx="4"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M8.5 21h7"/></svg>',
 building:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 21V5l8-3 8 3v16M2 21h20M8 7h2M14 7h2M8 11h2M14 11h2M8 15h2M14 15h2"/></svg>',
 sparkles:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m12 3 1.4 4.1L17.5 8.5l-4.1 1.4L12 14l-1.4-4.1-4.1-1.4 4.1-1.4L12 3ZM19 14l.8 2.2L22 17l-2.2.8L19 20l-.8-2.2L16 17l2.2-.8L19 14ZM5 14l.7 1.8 1.8.7-1.8.7L5 19l-.7-1.8-1.8-.7 1.8-.7L5 14Z"/></svg>',
 user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M4 21c.8-4.4 3.4-6.5 8-6.5s7.2 2.1 8 6.5"/></svg>',logout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M10 4H5v16h5M14 8l4 4-4 4M9 12h9"/></svg>'
};
const G={Action:'Ação',Adventure:'Aventura',Comedy:'Comédia',Drama:'Drama',Fantasy:'Fantasia',Horror:'Terror',Mystery:'Mistério',Romance:'Romance','Sci-Fi':'Ficção Científica','Slice of Life':'Slice of Life',Sports:'Esportes',Supernatural:'Sobrenatural',Thriller:'Suspense',Music:'Música',Psychological:'Psicológico'};
const F={TV:'Série',TV_SHORT:'Série curta',MOVIE:'Filme',SPECIAL:'Especial',OVA:'OVA',ONA:'ONA',MUSIC:'Música'};
const SEASONS={WINTER:'Inverno',SPRING:'Primavera',SUMMER:'Verão',FALL:'Outono'};
const DOW=['DOM','SEG','TER','QUA','QUI','SEX','SÁB'],DOW_FULL=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];

function injectIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{const k=el.dataset.icon;if(ICON[k])el.innerHTML=ICON[k]});}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function api(url,opts={}){return fetch(url,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||'REQUEST_FAILED'),{status:r.status,data:d});return d})}
function toast(msg,type='ok'){const n=document.createElement('div');n.className=`toast toast--${type}`;n.textContent=msg;document.querySelector('#toastStack').append(n);setTimeout(()=>n.remove(),3600)}
function track(event,mediaId){api('/api/events',{method:'POST',body:JSON.stringify({event,path:location.pathname,mediaId})}).catch(()=>{})}
function genre(g){return G[g]||g}function format(f){return F[f]||f||'Anime'}
function fmtDate(d){if(!d?.year)return '—';const dt=new Date(Date.UTC(d.year,(d.month||1)-1,d.day||1));return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(dt)}
function fmtTime(ts){return new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:TZ}).format(new Date(ts*1000))}
function dayKey(ts){return new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:TZ}).format(new Date(ts*1000))}
function todayKey(){return new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:TZ}).format(new Date())}
function nextDays(n=7){const key=todayKey(),base=new Date(`${key}T12:00:00-03:00`);return Array.from({length:n},(_,i)=>{const d=new Date(base.getTime()+i*864e5);const k=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:TZ}).format(d);const parts=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',timeZone:TZ}).formatToParts(d);return {key:k,date:d,day:Number(parts.find(x=>x.type==='day').value),dow:DOW[d.getDay()],full:DOW_FULL[d.getDay()]}})}
function currentSeason(){const d=new Date(),m=Number(new Intl.DateTimeFormat('en',{month:'numeric',timeZone:TZ}).format(d)),y=Number(new Intl.DateTimeFormat('en',{year:'numeric',timeZone:TZ}).format(d));return {season:m<=3?'WINTER':m<=6?'SPRING':m<=9?'SUMMER':'FALL',year:y}}
function seasonShift(season,year,delta){const arr=['WINTER','SPRING','SUMMER','FALL'];let i=arr.indexOf(season)+delta,y=year;while(i<0){i+=4;y--}while(i>3){i-=4;y++}return {season:arr[i],year:y}}
function score(m){return m.score?`<span class="score-pill">${ICON.star}${m.score.toFixed(1)}</span>`:''}
function poster(m){return `<div class="poster"><img loading="lazy" src="${esc(m.cover)}" alt="${esc(m.title)}"/>${score(m)}<span class="media-type">${esc(format(m.format))}</span></div>`}
function mediaCard(m){return `<article class="media-card" data-open-anime="${m.id}" tabindex="0">${poster(m)}<h3>${esc(m.title)}</h3><p>${esc((m.genres||[]).slice(0,2).map(genre).join(', '))}</p></article>`}
function skeleton(count=12){return `<div class="skeleton-grid">${Array.from({length:count},()=>'<div class="skeleton-card skeleton"></div>').join('')}</div>`}
function empty(title='Nada por aqui',text='Não encontramos resultados com os filtros atuais.'){return `<div class="empty"><img src="/assets/logo-192-small.png" alt=""><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function routeAnime(m){return `/anime/${m.slug||('anime-'+m.id)}`}
function setMeta(title){document.title=`${title} | AniNexus`}
function pageHero(title,subtitle,accent=''){return `<section class="page-hero page-hero--center"><div class="shell"><h1>${accent?`<span class="accent">${esc(accent)}</span> `:''}${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></section>`}

async function loadMe(){try{const d=await api('/api/me');state.user=d.user;if(state.user){const l=await api('/api/me/list').catch(()=>({items:[]}));state.list=new Map((l.items||[]).map(x=>[Number(x.media_id),x]))}}catch{}renderAuthHeader()}
function renderAuthHeader(){const a=document.querySelector('#authActions'),d=document.querySelector('#drawerAuth');if(!a||!d)return;if(state.user){a.innerHTML=`<a class="btn btn--ghost btn--small" href="/perfil" data-route>${ICON.user} ${esc(state.user.username)}</a><button class="round-action" data-action="logout" title="Sair">${ICON.logout}</button>`;d.innerHTML=`<a class="btn btn--ghost" href="/perfil" data-route>Meu perfil</a><button class="btn btn--ghost" data-action="logout">Sair</button>`}else{a.innerHTML=`<button class="btn btn--ghost btn--small" data-action="login">Entrar</button><button class="btn btn--primary btn--small" data-action="register">Criar conta ${ICON.arrow}</button>`;d.innerHTML=`<button class="btn btn--ghost" data-action="login">Entrar</button><button class="btn btn--primary" data-action="register">Criar conta</button>`}injectIcons(a);injectIcons(d)}
function setTheme(theme){state.theme=theme;localStorage.setItem('aninexus:theme',theme);document.documentElement.dataset.theme=theme;const t=document.querySelector('[data-action="theme"]');if(t)t.innerHTML=theme==='dark'?ICON.moon:ICON.sun}

function navigate(path,push=true){if(push)history.pushState({},'',path);renderRoute();document.querySelector('#mobileDrawer').hidden=true;window.scrollTo({top:0,behavior:'instant'});}
function updateNav(path){document.querySelectorAll('.desktop-nav a').forEach(a=>a.classList.remove('is-active'));const key=path==='/'?'home':path.includes('catalogo')?'catalog':path.includes('programacao')?'schedule':path.includes('temporadas')?'seasons':path.includes('listas')||path.includes('melhores')||path.includes('assistidos')||path.includes('aguardados')?'discover':'';document.querySelector(`[data-nav="${key}"]`)?.classList.add('is-active')}

async function renderHome(){setMeta('Início');app.innerHTML=`<div class="page"><section class="hero-home"><div class="shell hero-home__inner"><div><div class="eyebrow">Descubra seu próximo anime</div><h1>Avalie. Descubra.<span>Compartilhe.</span></h1><p>Temporadas, calendário de episódios, rankings e sua lista pessoal em uma experiência feita para quem acompanha anime no Brasil.</p><div class="hero-actions"><a class="btn btn--primary" href="/animes/temporadas" data-route>Explorar temporada ${ICON.arrow}</a><a class="btn btn--ghost" href="/animes/programacao" data-route>Ver programação</a></div></div><div class="hero-preview"><div class="orbit"></div><div class="hero-logo-glow"><img src="/assets/logo.png" alt="AniNexus"></div></div></div></section><section class="section"><div class="shell"><div class="section-title-row"><div><h2>Animes da Temporada</h2><p>O que está em destaque agora.</p></div><a class="section-link" href="/animes/temporadas" data-route>ver todos da temporada →</a></div><div id="homeSeason">${skeleton(6)}</div></div></section><section class="section"><div class="shell"><div class="section-title-row"><div><h2>Próximos episódios e lançamentos</h2><p>Acompanhe o que estreia hoje no horário de Brasília.</p></div><a class="section-link" href="/animes/programacao" data-route>programação →</a></div><div id="homeSchedule"><div class="schedule-grid">${Array.from({length:6},()=>'<div class="media-card--wide skeleton" style="height:178px"></div>').join('')}</div></div></div></section><section class="section"><div class="shell"><div class="section-title-row"><div><h2>Mais populares</h2><p>Os títulos com maior alcance no catálogo.</p></div><a class="section-link" href="/animes-mais-assistidos" data-route>ver ranking →</a></div><div id="homePopular">${skeleton(6)}</div></div></section></div>`;bindDynamic();
 const s=currentSeason();Promise.allSettled([api(`/api/catalog?page=1&perPage=12&season=${s.season}&year=${s.year}&sort=POPULAR`),api('/api/catalog?page=1&perPage=12&sort=POPULAR'),api(`/api/schedule?start=${Math.floor(Date.now()/1000)-3600}&end=${Math.floor(Date.now()/1000)+86400}`)]).then(([season,pop,sch])=>{if(season.status==='fulfilled')document.querySelector('#homeSeason').innerHTML=`<div class="media-grid">${season.value.items.slice(0,6).map(mediaCard).join('')}</div>`;if(pop.status==='fulfilled')document.querySelector('#homePopular').innerHTML=`<div class="media-grid">${pop.value.items.slice(0,6).map(mediaCard).join('')}</div>`;if(sch.status==='fulfilled')document.querySelector('#homeSchedule').innerHTML=`<div class="schedule-grid">${sch.value.slice(0,6).map(scheduleCard).join('')}</div>`;bindDynamic();}).catch(()=>{});
}

function scheduleCard(x){const m=x.media,when=dayKey(x.airingAt)===todayKey()?'Hoje':new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',timeZone:TZ}).format(new Date(x.airingAt*1000));return `<article class="media-card--wide" data-open-anime="${m.id}" tabindex="0"><div class="wide-cover"><img loading="lazy" src="${esc(m.cover)}" alt="${esc(m.title)}">${m.score?`<span class="wide-score">★ ${m.score.toFixed(1)}</span>`:''}<button class="cover-action cover-action--plus" data-list="${m.id}" aria-label="Adicionar à lista">${ICON.plus}</button><button class="cover-action cover-action--heart" data-fav="${m.id}" aria-label="Quero ver">${ICON.heart}</button></div><div class="wide-body"><div class="wide-time">${esc(when)} <strong>${fmtTime(x.airingAt)}</strong></div><h3>${esc(m.title)}</h3><div class="wide-genres">${esc((m.genres||[]).slice(0,3).map(genre).join(', '))}</div><div class="ep-number"><small>EP</small>${x.episode}</div></div></article>`}

async function renderSchedule(){setMeta('Programação de Animes');const days=nextDays(),start=Math.floor(Date.now()/1000)-12*3600,end=start+8*86400;app.innerHTML=`<div class="page">${pageHero('Calendário de Animes da Semana','Acompanhe os dias e horários de lançamento dos episódios, no horário de Brasília.')}<div class="shell"><div class="week-controls"><div class="days">${days.map((d,i)=>`<button class="day-chip ${i===0?'is-active':''}" data-scroll-day="${d.key}"><small>${d.dow}</small><strong>${d.day}</strong></button>`).join('')}</div><span class="week-sep"></span><button class="pill-button" data-action="fav-filter">${ICON.heart} Meus animes</button><button class="pill-button" data-action="stream-filter">${ICON.play} Onde assistir</button></div></div><section class="section"><div class="shell" id="scheduleContent"><div class="schedule-grid">${Array.from({length:9},()=>'<div class="media-card--wide skeleton" style="height:178px"></div>').join('')}</div></div></section></div>`;bindDynamic();
 const load=async(silent=false)=>{try{const data=await api(`/api/schedule?start=${start}&end=${end}`),key=JSON.stringify(data.map(x=>[x.airingAt,x.episode,x.media.id]));if(silent&&state._scheduleKey===key)return;state._scheduleKey=key;state._schedule=data;drawSchedule(days)}catch(e){if(!silent)document.querySelector('#scheduleContent').innerHTML='<div class="error-box">Não foi possível carregar a programação agora.</div>'}};await load(false);clearInterval(state.scheduleTimer);state.scheduleTimer=setInterval(()=>{if(location.pathname==='/animes/programacao')load(true)},30000);}
function drawSchedule(days){const favOnly=!!state._favOnly,streamOnly=!!state._streamOnly;const filtered=(state._schedule||[]).filter(x=>(!favOnly||state.list.has(x.media.id))&&(!streamOnly||(x.media.streaming||[]).length));const grouped=Object.groupBy(filtered,x=>dayKey(x.airingAt));document.querySelector('#scheduleContent').innerHTML=days.map(d=>{const items=grouped[d.key]||[];return `<section class="day-section" id="day-${d.key}"><div class="day-heading"><h2>${d.full}-feira`.replace('Domingo-feira','Domingo').replace('Sábado-feira','Sábado')+`</h2><span class="line"></span><span class="count">${items.length} episódios</span></div>${items.length?`<div class="schedule-grid">${items.map(scheduleCard).join('')}</div>`:empty('Sem episódios neste dia','Nenhum lançamento foi encontrado para esta data.')}</section>`}).join('');bindDynamic();}

async function renderCatalog(){setMeta('Catálogo de Animes');app.innerHTML=`<div class="page">${pageHero('Catálogo de Animes','Explore títulos, encontre clássicos e descubra algo novo para assistir.')}<section class="section"><div class="shell"><div class="filters-panel"><div class="field"><label>Pesquisar</label><input id="catSearch" value="${esc(state.catalogFilters.search)}" placeholder="Nome do anime..."></div><div class="field"><label>Gênero</label><select id="catGenre"><option value="">Todos</option>${['Action','Adventure','Comedy','Drama','Fantasy','Horror','Mystery','Romance','Sci-Fi','Slice of Life','Sports','Supernatural'].map(x=>`<option value="${x}" ${state.catalogFilters.genre===x?'selected':''}>${genre(x)}</option>`).join('')}</select></div><div class="field"><label>Formato</label><select id="catFormat"><option value="">Todos</option>${Object.entries(F).map(([k,v])=>`<option value="${k}" ${state.catalogFilters.format===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Ordenar</label><select id="catSort"><option value="POPULAR">Popularidade</option><option value="SCORE">Melhor nota</option><option value="TRENDING">Em alta</option><option value="NEW">Mais recentes</option><option value="TITLE">Título</option></select></div></div><div class="section-title-row"><div><h2>Todos os animes</h2><p class="catalog-count" id="catalogCount">Carregando...</p></div></div><div id="catalogGrid">${skeleton(18)}</div><div id="catalogPages"></div></div></section></div>`;document.querySelector('#catSort').value=state.catalogFilters.sort;['catGenre','catFormat','catSort'].forEach(id=>document.querySelector('#'+id).addEventListener('change',()=>{state.catalogFilters.genre=document.querySelector('#catGenre').value;state.catalogFilters.format=document.querySelector('#catFormat').value;state.catalogFilters.sort=document.querySelector('#catSort').value;state.catalogPage=1;loadCatalog()}));document.querySelector('#catSearch').addEventListener('input',e=>{clearTimeout(state._catDeb);state._catDeb=setTimeout(()=>{state.catalogFilters.search=e.target.value.trim();state.catalogPage=1;loadCatalog()},350)});loadCatalog();}
async function loadCatalog(){const f=state.catalogFilters,q=new URLSearchParams({page:state.catalogPage,perPage:24,sort:f.sort});if(f.search)q.set('search',f.search);if(f.genre)q.set('genre',f.genre);if(f.format)q.set('format',f.format);try{const d=await api('/api/catalog?'+q);document.querySelector('#catalogCount').textContent=`${Number(d.pageInfo.total||0).toLocaleString('pt-BR')} títulos encontrados`;document.querySelector('#catalogGrid').innerHTML=d.items.length?`<div class="media-grid">${d.items.map(mediaCard).join('')}</div>`:empty();document.querySelector('#catalogPages').innerHTML=pager(d.pageInfo,'catalog');bindDynamic()}catch{document.querySelector('#catalogGrid').innerHTML='<div class="error-box">Não foi possível carregar o catálogo.</div>'}}
function pager(info,type){const cur=Number(info.currentPage||1),last=Math.min(Number(info.lastPage||cur),cur+4),start=Math.max(1,cur-2);return `<div class="pagination">${cur>1?`<button class="page-btn" data-page="${cur-1}" data-page-type="${type}">‹</button>`:''}${Array.from({length:last-start+1},(_,i)=>start+i).map(p=>`<button class="page-btn ${p===cur?'is-active':''}" data-page="${p}" data-page-type="${type}">${p}</button>`).join('')}${info.hasNextPage?`<button class="page-btn" data-page="${cur+1}" data-page-type="${type}">›</button>`:''}</div>`}

async function renderSeasons(){const base=state.season||currentSeason();state.season=base;setMeta(`Temporada ${SEASONS[base.season]} ${base.year}`);app.innerHTML=`<div class="page">${pageHero(`Animes da Temporada ${SEASONS[base.season]} ${base.year}`,'Veja estreias, continuações e títulos em exibição nesta temporada.')}<div class="shell"><div class="season-switcher"><button class="switch-btn" data-season-shift="-1">${ICON.left}</button><div class="season-tabs">${Object.entries(SEASONS).map(([k,v])=>`<button data-season="${k}" class="${k===base.season?'is-active':''}">${v}</button>`).join('')}</div><select class="year-select" id="seasonYear">${Array.from({length:12},(_,i)=>currentSeason().year+2-i).map(y=>`<option ${y===base.year?'selected':''}>${y}</option>`).join('')}</select><button class="switch-btn" data-season-shift="1">${ICON.right}</button></div></div><section class="section"><div class="shell"><div class="section-title-row"><div><h2>${SEASONS[base.season]} ${base.year}</h2><p id="seasonCount">Carregando...</p></div></div><div id="seasonGrid">${skeleton(18)}</div><div id="seasonPages"></div></div></section></div>`;document.querySelectorAll('[data-season]').forEach(b=>b.addEventListener('click',()=>{state.season={season:b.dataset.season,year:state.season.year};renderSeasons()}));document.querySelectorAll('[data-season-shift]').forEach(b=>b.addEventListener('click',()=>{state.season=seasonShift(state.season.season,state.season.year,Number(b.dataset.seasonShift));renderSeasons()}));document.querySelector('#seasonYear').addEventListener('change',e=>{state.season.year=Number(e.target.value);renderSeasons()});loadSeason(1)}
async function loadSeason(page){const s=state.season;try{const d=await api(`/api/catalog?page=${page}&perPage=24&season=${s.season}&year=${s.year}&sort=POPULAR`);document.querySelector('#seasonCount').textContent=`${Number(d.pageInfo.total||0).toLocaleString('pt-BR')} títulos`;document.querySelector('#seasonGrid').innerHTML=d.items.length?`<div class="media-grid">${d.items.map(mediaCard).join('')}</div>`:empty();document.querySelector('#seasonPages').innerHTML=pager(d.pageInfo,'season');bindDynamic()}catch{document.querySelector('#seasonGrid').innerHTML='<div class="error-box">Não foi possível carregar a temporada.</div>'}}

async function renderStreaming(){setMeta('Onde Assistir Animes');app.innerHTML=`<div class="page">${pageHero('Onde Assistir Animes','Descubra plataformas disponíveis nos títulos do catálogo e acesse as opções oficiais de exibição.')}<section class="section"><div class="shell"><div class="section-title-row"><div><h2>Plataformas encontradas</h2><p>Disponibilidade pode mudar conforme região e licenciamento.</p></div></div><div id="streamProviders"><div class="streaming-grid">${Array.from({length:8},()=>'<div class="stream-card skeleton"></div>').join('')}</div></div><div class="section-title-row" style="margin-top:36px"><div><h2>Animes com opções de streaming</h2></div></div><div id="streamAnime">${skeleton(18)}</div></div></section></div>`;try{const d=await api('/api/catalog?page=1&perPage=30&sort=POPULAR'),map=new Map();d.items.forEach(m=>(m.streaming||[]).forEach(x=>{if(!map.has(x.site))map.set(x.site,{count:0,items:[]});const v=map.get(x.site);v.count++;v.items.push(m)}));const providers=[...map.entries()].sort((a,b)=>b[1].count-a[1].count);document.querySelector('#streamProviders').innerHTML=providers.length?`<div class="streaming-grid">${providers.map(([name,v])=>`<article class="stream-card" data-platform="${esc(name)}"><div class="stream-card__icon">${ICON.play}</div><h3>${esc(name)}</h3><p>${v.count} títulos nesta amostra</p></article>`).join('')}</div>`:empty('Nenhuma plataforma identificada','A disponibilidade será exibida quando houver links oficiais confirmados.');const items=d.items.filter(m=>(m.streaming||[]).length);document.querySelector('#streamAnime').innerHTML=items.length?`<div class="media-grid">${items.map(mediaCard).join('')}</div>`:empty();bindDynamic()}catch{document.querySelector('#streamProviders').innerHTML='<div class="error-box">Não foi possível carregar as plataformas.</div>'}}

async function renderDubbed(){setMeta('Animes Dublados');app.innerHTML=`<div class="page">${pageHero('Animes Dublados','Títulos com dublagem em português confirmada no cadastro do AniNexus.')}<section class="section"><div class="shell"><div id="dubGrid">${skeleton(18)}</div></div></section></div>`;try{const d=await api('/api/dublados?page=1');document.querySelector('#dubGrid').innerHTML=d.items.length?`<div class="media-grid">${d.items.map(mediaCard).join('')}</div>`:empty('Ainda não há títulos confirmados','A dublagem só aparece quando foi confirmada no cadastro interno.');bindDynamic()}catch{document.querySelector('#dubGrid').innerHTML='<div class="error-box">Não foi possível carregar os títulos dublados.</div>'}}

async function renderStudios(){setMeta('Estúdios de Anime');app.innerHTML=`<div class="page">${pageHero('Estúdios de Anime','Explore estúdios e alguns dos títulos associados a cada catálogo.')}<section class="section"><div class="shell"><div id="studiosGrid"><div class="studio-grid">${Array.from({length:9},()=>'<div class="studio-card skeleton" style="height:220px"></div>').join('')}</div></div></div></section></div>`;try{const d=await api('/api/studios?page=1');document.querySelector('#studiosGrid').innerHTML=`<div class="studio-grid">${d.items.map(s=>`<article class="studio-card"><h3>${esc(s.name)}</h3><div class="studio-card__covers">${s.media.slice(0,4).map(m=>`<img loading="lazy" src="${esc(m.cover)}" alt="${esc(m.title)}" data-open-anime="${m.id}" tabindex="0">`).join('')}</div></article>`).join('')}</div>`;bindDynamic()}catch{document.querySelector('#studiosGrid').innerHTML='<div class="error-box">Não foi possível carregar os estúdios.</div>'}}

async function renderListsIndex(){setMeta('Listas de Animes');app.innerHTML=`<div class="page">${pageHero('Listas de Animes','Rankings e seleções para descobrir o que assistir depois.')}<section class="section"><div class="shell"><div class="streaming-grid"><a class="stream-card" href="/melhores-animes-para-assistir" data-route><div class="stream-card__icon">${ICON.star}</div><h3>Melhores Animes</h3><p>Os títulos mais bem avaliados.</p></a><a class="stream-card" href="/animes-mais-assistidos" data-route><div class="stream-card__icon">${ICON.users}</div><h3>Mais Assistidos</h3><p>Os mais populares do catálogo.</p></a><a class="stream-card" href="/animes-mais-aguardados" data-route><div class="stream-card__icon">${ICON.sparkles}</div><h3>Mais Aguardados</h3><p>Os títulos que estão em alta.</p></a></div></div></section></div>`;bindDynamic()}
async function renderRanking(slug){const labels={ 'melhores-animes-para-assistir':'Melhores animes para assistir','animes-mais-assistidos':'Animes mais assistidos','animes-mais-aguardados':'Animes mais aguardados'};setMeta(labels[slug]||'Lista');app.innerHTML=`<div class="page"><section class="list-hero"><div class="shell"><div class="eyebrow">Lista AniNexus</div><h1>${esc(labels[slug]||'Lista')}</h1><p>Uma seleção dinâmica organizada pelos sinais disponíveis no catálogo.</p></div></section><section class="section"><div class="shell"><div id="rankList" class="rank-list">${Array.from({length:8},()=>'<div class="rank-row skeleton" style="height:142px"></div>').join('')}</div></div></section></div>`;try{const d=await api(`/api/list/${slug}?page=1`);document.querySelector('#rankList').innerHTML=d.items.slice(0,20).map((m,i)=>`<article class="rank-row" data-open-anime="${m.id}" tabindex="0"><div class="rank-num">${String(i+1).padStart(2,'0')}</div><img loading="lazy" src="${esc(m.cover)}" alt="${esc(m.title)}"><div class="rank-main"><h3>${esc(m.title)}</h3><p>${esc((m.genres||[]).slice(0,4).map(genre).join(' · '))}</p></div><div class="rank-score">${m.score?m.score.toFixed(1):'—'}</div></article>`).join('');bindDynamic()}catch{document.querySelector('#rankList').innerHTML='<div class="error-box">Não foi possível carregar esta lista.</div>'}}

async function renderAnime(path){const id=Number(path.match(/-(\d+)\/?$/)?.[1]||path.match(/\/anime\/(\d+)\/?$/)?.[1]);if(!id){return renderNotFound()}setMeta('Anime');app.innerHTML=`<div class="page"><div class="anime-hero skeleton" style="height:430px"></div></div>`;try{const m=await api(`/api/anime/${id}`);setMeta(m.title);const list=state.list.get(m.id);app.innerHTML=`<div class="page"><section class="anime-hero"><div class="anime-backdrop" style="background-image:url('${esc(m.banner||m.cover)}')"></div><div class="shell anime-hero__inner"><img class="anime-poster" src="${esc(m.cover)}" alt="${esc(m.title)}"><div class="anime-info"><div class="alt-title">${esc(m.titleRomaji||m.titleNative||'')}</div><h1>${esc(m.title)}</h1><div class="tag-row">${[m.seasonYear,format(m.format),m.dubbed?'Dublado':null,m.subtitled?'Legendado':null,...(m.genres||[]).slice(0,6).map(genre)].filter(Boolean).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="anime-actions"><button class="btn btn--primary" data-list="${m.id}">${list?'Na minha lista':'Adicionar à Lista'}</button>${m.streaming?.[0]?`<a class="btn btn--ghost" href="${esc(m.streaming[0].url)}" target="_blank" rel="noopener noreferrer">${ICON.play} Onde assistir</a>`:''}</div><div class="stats-row"><div class="stat"><strong>${m.score?m.score.toFixed(1):'—'}</strong><span>nota média</span></div><div class="stat"><strong>${Number(m.popularity||0).toLocaleString('pt-BR')}</strong><span>popularidade</span></div><div class="stat"><strong>${m.episodes||'—'}</strong><span>episódios</span></div>${m.nextAiringEpisode?`<div class="stat"><strong>${fmtTime(m.nextAiringEpisode.airingAt)}</strong><span>próximo episódio</span></div>`:''}</div></div></div></section><nav class="anime-tabs"><div class="shell anime-tabs__inner"><button class="is-active" data-anime-tab="geral">Geral</button><button data-anime-tab="impressoes">Impressões</button><button data-anime-tab="franquia">Franquia</button><button data-anime-tab="recomendacoes">Recomendações</button><button data-anime-tab="compartilhar">Compartilhar</button></div></nav><section class="section"><div class="shell" id="animeTabContent">${renderAnimeGeneral(m)}</div></section></div>`;state._anime=m;bindDynamic();track('anime_view',m.id)}catch{renderNotFound()}}
function renderAnimeGeneral(m){return `<div class="anime-layout"><div><p class="anime-copy">${esc(m.description||'Sinopse ainda não cadastrada.')}</p>${m.streaming?.length?`<div class="watch-box"><h3>Onde assistir ${esc(m.title)}</h3><div class="watch-links">${m.streaming.map(x=>`<a class="watch-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${ICON.play}${esc(x.site)}</a>`).join('')}</div></div>`:''}${m.characters?.length?`<div class="section-title-row" style="margin-top:34px"><div><h2>Personagens</h2></div></div><div class="people-row">${m.characters.map(p=>`<article class="person-card"><img loading="lazy" src="${esc(p.image)}" alt="${esc(p.name)}"><strong>${esc(p.name)}</strong><span>${p.role==='MAIN'?'Principal':'Secundário'}</span></article>`).join('')}</div>`:''}${m.staff?.length?`<div class="section-title-row" style="margin-top:34px"><div><h2>Equipe</h2></div></div><div class="people-row">${m.staff.slice(0,6).map(p=>`<article class="person-card"><img loading="lazy" src="${esc(p.image)}" alt="${esc(p.name)}"><strong>${esc(p.name)}</strong><span>${esc(p.role)}</span></article>`).join('')}</div>`:''}</div><aside><div class="details-card"><div class="details-list">${detailRow('Origem',m.country==='JP'?'Japão':m.country||'—')}${detailRow('Tipo',format(m.format))}${detailRow('Episódios',m.episodes||'—')}${detailRow('Ano',m.seasonYear||'—')}${detailRow('Temporada',SEASONS[m.season]||'—')}${detailRow('Início',fmtDate(m.startDate))}${detailRow('Duração',m.duration?`${m.duration}min`:'—')}${detailRow('Status',statusName(m.status))}${detailRow('Baseado em',sourceName(m.source))}${detailRow('Estúdios',(m.studios||[]).map(x=>x.name).join(', ')||'—')}</div></div>${m.titleRomaji||m.titleNative?`<div class="details-card" style="margin-top:14px"><h3>Outros títulos</h3><div class="details-list">${m.titleRomaji?detailRow('Romaji',m.titleRomaji):''}${m.titleNative?detailRow('Japonês',m.titleNative):''}</div></div>`:''}</aside></div>`}
function detailRow(k,v){return `<div class="details-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`}function statusName(s){return ({RELEASING:'Em andamento',FINISHED:'Finalizado',NOT_YET_RELEASED:'Ainda não lançado',CANCELLED:'Cancelado',HIATUS:'Em pausa'})[s]||s||'—'}function sourceName(s){return ({MANGA:'Mangá',LIGHT_NOVEL:'Light novel',ORIGINAL:'Original',NOVEL:'Novel',VIDEO_GAME:'Jogo',VISUAL_NOVEL:'Visual novel',WEB_NOVEL:'Web novel'})[s]||s||'—'}
async function showAnimeTab(tab){const m=state._anime;if(!m)return;document.querySelectorAll('[data-anime-tab]').forEach(b=>b.classList.toggle('is-active',b.dataset.animeTab===tab));const root=document.querySelector('#animeTabContent');if(tab==='geral')root.innerHTML=renderAnimeGeneral(m);if(tab==='franquia')root.innerHTML=m.relations?.length?`<div class="media-grid">${m.relations.map(x=>mediaCard(x.media)).join('')}</div>`:empty('Sem relações cadastradas');if(tab==='recomendacoes')root.innerHTML=m.recommendations?.length?`<div class="media-grid">${m.recommendations.map(x=>mediaCard(x.media)).join('')}</div>`:empty('Sem recomendações cadastradas');if(tab==='compartilhar'){root.innerHTML=`<div class="form-card"><h2>Compartilhar</h2><p style="color:var(--muted)">Copie o link desta página para enviar para seus amigos.</p><button class="btn btn--primary" data-action="copy-url">Copiar link</button></div>`}if(tab==='impressoes'){root.innerHTML=`<div class="anime-layout"><div><div id="impressionsList">Carregando...</div></div><aside>${state.user?`<form class="impression-box" id="impressionForm"><div class="field"><label>Sua impressão</label><textarea name="body" maxlength="1200" placeholder="Conte o que achou..."></textarea></div><label style="display:flex;gap:8px;align-items:center;margin:10px 0;font-size:12px;color:var(--muted)"><input type="checkbox" name="spoiler"> contém spoiler</label><button class="btn btn--primary" type="submit">Publicar</button></form>`:`<div class="details-card"><h3>Participe da conversa</h3><p style="color:var(--muted);font-size:13px">Entre na sua conta para registrar uma impressão.</p><button class="btn btn--primary" data-action="login">Entrar</button></div>`}</aside></div>`;loadImpressions(m.id)}bindDynamic()}
async function loadImpressions(id){try{const d=await api(`/api/anime/${id}/impressions`),r=document.querySelector('#impressionsList');r.innerHTML=d.items.length?`<div class="impression-box">${d.items.map(x=>`<article class="impression-item"><div class="impression-head"><strong>@${esc(x.username)}</strong><span>${new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium'}).format(new Date(x.created_at))}</span></div><p class="${x.spoiler?'spoiler':''}" title="Passe o mouse para revelar spoiler">${esc(x.body)}</p></article>`).join('')}</div>`:empty('Ainda não há impressões','Seja a primeira pessoa a comentar este anime.')}catch{}}

async function renderProfile(){if(!state.user){openAuth('login');navigate('/',false);return}setMeta('Meu Perfil');app.innerHTML=`<div class="page"><section class="profile-hero"><div class="shell profile-card"><div class="profile-avatar"><img src="${esc(state.user.avatarUrl||'/assets/logo-192-small.png')}" alt=""></div><div class="profile-meta"><div class="eyebrow">Minha conta</div><h1>${esc(state.user.username)}</h1><p>${esc(state.user.email)}</p></div></div></section><section class="section"><div class="shell"><div id="profileStats" class="status-grid"></div><div class="section-title-row" style="margin-top:34px"><div><h2>Minha lista</h2><p>Seus animes organizados por status.</p></div></div><div id="profileList">Carregando...</div></div></section></div>`;try{const l=await api('/api/me/list');const counts={PLANNING:0,CURRENT:0,COMPLETED:0,PAUSED:0,DROPPED:0};l.items.forEach(x=>counts[x.status]++);document.querySelector('#profileStats').innerHTML=[['PLANNING','Quero ver'],['CURRENT','Assistindo'],['COMPLETED','Terminei'],['PAUSED','Pausei'],['DROPPED','Desisti']].map(([k,v])=>`<div class="status-card"><strong>${counts[k]}</strong><span>${v}</span></div>`).join('');if(!l.items.length){document.querySelector('#profileList').innerHTML=empty('Sua lista está vazia','Adicione animes pelo catálogo ou pelas páginas individuais.');return}const media=await Promise.all(l.items.slice(0,30).map(x=>api('/api/anime/'+x.media_id).catch(()=>null)));document.querySelector('#profileList').innerHTML=`<div class="media-grid">${media.filter(Boolean).map(mediaCard).join('')}</div>`;bindDynamic()}catch{}}

function renderStatic(path){const P={
'/quem-somos':['Quem Somos','Anime, descoberta e comunidade em português',['O AniNexus reúne programação, temporadas, catálogo, listas pessoais e descoberta de animes em uma experiência criada para o público brasileiro.','A plataforma foi construída para ser rápida em celulares, computadores, tablets e telas grandes, com recursos de acessibilidade e navegação por teclado.']],
'/colabore':['Colabore','Ajude o AniNexus a ficar cada vez melhor.',['Você pode enviar correções sobre títulos em português, disponibilidade, dublagem, sinopses e informações editoriais. As contribuições passam por revisão antes de serem publicadas.']],
'/termos-de-uso':['Termos de Serviço','Regras de uso da plataforma.',['Ao utilizar o AniNexus você concorda em não explorar vulnerabilidades, automatizar abuso, praticar fraude, spam ou interferir na experiência de terceiros.','Contas podem ser limitadas ou suspensas por abuso. Direitos sobre obras, marcas, personagens e imagens permanecem com seus respectivos titulares.']],
'/politica-de-privacidade':['Política de Privacidade','Como tratamos informações da sua conta.',['Armazenamos os dados necessários para operar contas, listas, preferências, suporte, segurança e métricas do produto. Senhas são guardadas somente na forma de hash criptográfico.','Você pode solicitar correção ou exclusão de dados pessoais. Registros técnicos de segurança podem ser mantidos por prazo limitado para prevenção de fraude e investigação de incidentes.']]
}[path];if(!P)return renderNotFound();setMeta(P[0]);app.innerHTML=`<div class="page"><section class="static-page"><div class="shell static-card"><div class="eyebrow">AniNexus</div><h1>${esc(P[0])}</h1><p style="font-weight:800;color:var(--text)">${esc(P[1])}</p>${P[2].map(x=>`<p>${esc(x)}</p>`).join('')}</div></section></div>`}
function renderContact(){setMeta('Contato');app.innerHTML=`<div class="page"><section class="static-page"><div class="shell static-card"><div class="eyebrow">Contato</div><h1>Fale com o AniNexus</h1><p>Dúvidas, sugestões, correções e assuntos comerciais podem ser enviados por este formulário.</p><form class="form-card" id="contactForm"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" required minlength="2"></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field full"><label>Assunto</label><input name="subject" required minlength="3"></div><div class="field full"><label>Mensagem</label><textarea name="message" required minlength="10"></textarea></div><div class="full"><button class="btn btn--primary">Enviar mensagem</button><div class="form-status" id="contactStatus"></div></div></div></form></div></section></div>`;document.querySelector('#contactForm').addEventListener('submit',submitContact)}
async function submitContact(e){e.preventDefault();const f=new FormData(e.currentTarget),body=Object.fromEntries(f);const s=document.querySelector('#contactStatus');s.textContent='Enviando...';try{await api('/api/contact',{method:'POST',body:JSON.stringify(body)});s.textContent='Mensagem recebida. Obrigado!';e.currentTarget.reset()}catch{s.textContent='Não foi possível enviar agora.'}}
function renderDmca(){setMeta('DMCA');app.innerHTML=`<div class="page"><section class="static-page"><div class="shell static-card"><div class="eyebrow">Direitos autorais</div><h1>Solicitação de remoção</h1><p>O AniNexus respeita direitos autorais. Se você representa o titular de uma obra e acredita que determinado conteúdo deve ser removido, envie uma notificação completa pelo formulário abaixo.</p><p>Envie apenas solicitações de boa-fé e identifique com precisão o conteúdo, o direito alegado e a URL específica. Solicitações incompletas podem atrasar a análise.</p><form class="form-card" id="dmcaForm"><div class="form-grid"><div class="field"><label>Seu nome</label><input name="requesterName" required></div><div class="field"><label>Seu e-mail</label><input name="requesterEmail" type="email" required></div><div class="field full"><label>Titular dos direitos</label><input name="rightsHolder" required></div><div class="field full"><label>URL do conteúdo</label><input name="contentUrl" type="url" required></div><div class="field full"><label>Descrição da solicitação</label><textarea name="description" minlength="30" required></textarea></div><div class="field full"><label>Assinatura (nome completo)</label><input name="signature" required></div><label class="full" style="display:flex;gap:8px;align-items:flex-start;font-size:12px;color:var(--muted)"><input type="checkbox" name="goodFaith" required> Declaro, de boa-fé, que as informações fornecidas são corretas e que tenho autorização para agir em nome do titular.</label><div class="full"><button class="btn btn--primary">Enviar solicitação</button><div class="form-status" id="dmcaStatus"></div></div></div></form></div></section></div>`;document.querySelector('#dmcaForm').addEventListener('submit',submitDmca)}
async function submitDmca(e){e.preventDefault();const f=new FormData(e.currentTarget),body=Object.fromEntries(f);body.goodFaith=f.get('goodFaith')==='on';const s=document.querySelector('#dmcaStatus');s.textContent='Enviando...';try{await api('/api/dmca',{method:'POST',body:JSON.stringify(body)});s.textContent='Solicitação registrada para análise.';e.currentTarget.reset()}catch{s.textContent='Revise os campos e tente novamente.'}}
function renderNotFound(){setMeta('Página não encontrada');app.innerHTML=`<div class="page"><section class="static-page"><div class="shell static-card">${empty('Página não encontrada','O endereço que você tentou acessar não existe.')}<div style="text-align:center;margin-top:16px"><a class="btn btn--primary" href="/" data-route>Voltar ao início</a></div></div></section></div>`;bindDynamic()}

function openSearch(){searchLayer.hidden=false;searchLayer.setAttribute('aria-hidden','false');const i=document.querySelector('#globalSearch');i.value='';document.querySelector('#globalSearchResults').innerHTML='<div class="search-tip">Digite o nome de um anime para pesquisar.</div>';setTimeout(()=>i.focus(),30)}function closeSearch(){searchLayer.hidden=true;searchLayer.setAttribute('aria-hidden','true')}
async function searchGlobal(q){const r=document.querySelector('#globalSearchResults');if(!q.trim()){r.innerHTML='<div class="search-tip">Digite o nome de um anime para pesquisar.</div>';return}r.innerHTML='<div class="search-tip">Pesquisando...</div>';try{const d=await api('/api/catalog?'+new URLSearchParams({search:q,page:1,perPage:8,sort:'POPULAR'}));r.innerHTML=d.items.length?d.items.map(m=>`<div class="search-result" data-open-anime="${m.id}" tabindex="0"><img src="${esc(m.cover)}" alt=""><div><strong>${esc(m.title)}</strong><br><span>${esc(format(m.format))} · ${m.seasonYear||'—'}</span></div><div class="search-score">${m.score?m.score.toFixed(1):'—'}</div></div>`).join(''):'<div class="search-tip">Nenhum anime encontrado.</div>';bindDynamic()}catch{r.innerHTML='<div class="search-tip">Não foi possível pesquisar agora.</div>'}}
function openAuth(mode='login'){authLayer.hidden=false;authLayer.setAttribute('aria-hidden','false');renderAuth(mode)}function closeAuth(){authLayer.hidden=true;authLayer.setAttribute('aria-hidden','true')}
function renderAuth(mode){const reg=mode==='register';document.querySelector('#authContent').innerHTML=`<h2>${reg?'Criar sua conta':'Bem-vindo de volta'}</h2><p class="lead">${reg?'Organize seus animes e participe da comunidade.':'Entre para continuar sua lista.'}</p><form class="auth-form" id="authForm">${reg?`<div class="field"><label>Usuário</label><input name="username" minlength="3" maxlength="30" required autocomplete="username"></div>`:''}<div class="field"><label>${reg?'E-mail':'E-mail ou usuário'}</label><input name="${reg?'email':'login'}" ${reg?'type="email"':''} required autocomplete="${reg?'email':'username'}"></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="${reg?10:1}" required autocomplete="${reg?'new-password':'current-password'}"></div><button class="btn btn--primary" type="submit">${reg?'Criar conta':'Entrar'}</button></form><div class="auth-switch">${reg?'Já tem conta?':'Ainda não tem conta?'} <button type="button" data-auth-switch="${reg?'login':'register'}">${reg?'Entrar':'Criar conta'}</button></div>`;document.querySelector('#authForm').addEventListener('submit',e=>submitAuth(e,mode));document.querySelector('[data-auth-switch]').addEventListener('click',e=>renderAuth(e.currentTarget.dataset.authSwitch))}
async function submitAuth(e,mode){e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));const btn=e.currentTarget.querySelector('button[type=submit]');btn.disabled=true;btn.textContent='Aguarde...';try{const d=await api(`/api/auth/${mode}`,{method:'POST',body:JSON.stringify(body)});state.user=d.user;await loadMe();closeAuth();toast(mode==='login'?'Login realizado.':'Conta criada.');renderRoute()}catch(err){toast(err.status===409?'E-mail ou usuário já cadastrado.':err.status===401?'Dados de acesso incorretos.':'Não foi possível concluir.', 'error');btn.disabled=false;btn.textContent=mode==='login'?'Entrar':'Criar conta'}}

async function setList(mediaId,status='PLANNING'){if(!state.user){openAuth('login');return}try{await api(`/api/me/list/${mediaId}`,{method:'PUT',body:JSON.stringify({status})});state.list.set(Number(mediaId),{media_id:Number(mediaId),status});toast(status==='PLANNING'?'Adicionado à lista.':'Lista atualizada.');if(location.pathname.startsWith('/anime/'))renderAnime(location.pathname)}catch{toast('Não foi possível atualizar sua lista.','error')}}
function openListMenu(id,el){if(!state.user){openAuth('login');return}const statuses=[['PLANNING','Quero Ver'],['CURRENT','Assistindo'],['COMPLETED','Terminei'],['PAUSED','Pausei'],['DROPPED','Desisti']];const menu=document.createElement('div');menu.className='toast';menu.style.position='fixed';const r=el.getBoundingClientRect();menu.style.left=Math.min(r.left,innerWidth-210)+'px';menu.style.top=Math.min(r.bottom+8,innerHeight-230)+'px';menu.innerHTML=`<strong style="display:block;margin-bottom:8px">Adicionar à lista</strong>${statuses.map(([k,v])=>`<button class="btn btn--ghost btn--small" style="width:100%;margin:3px 0" data-set-status="${k}">${v}</button>`).join('')}`;document.body.append(menu);menu.querySelectorAll('[data-set-status]').forEach(b=>b.onclick=()=>{setList(id,b.dataset.setStatus);menu.remove()});setTimeout(()=>document.addEventListener('click',()=>menu.remove(),{once:true}),0)}

function bindDynamic(){document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.bound)return;a.dataset.bound='1';a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||a.target==='_blank')return;e.preventDefault();navigate(a.getAttribute('href'))})});document.querySelectorAll('[data-open-anime]').forEach(el=>{if(el.dataset.bound)return;el.dataset.bound='1';const go=()=>{closeSearch();navigate(`/anime/anime-${el.dataset.openAnime}`);track('anime_click',Number(el.dataset.openAnime))};el.addEventListener('click',e=>{if(e.target.closest('button,a'))return;go()});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})});document.querySelectorAll('[data-list]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();openListMenu(Number(b.dataset.list),b)})});document.querySelectorAll('[data-fav]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();setList(Number(b.dataset.fav),'PLANNING')})});document.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{const p=Number(b.dataset.page);if(b.dataset.pageType==='catalog'){state.catalogPage=p;loadCatalog()}else if(b.dataset.pageType==='season')loadSeason(p);window.scrollTo({top:220,behavior:'smooth'})})});document.querySelectorAll('[data-scroll-day]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{document.querySelector('#day-'+b.dataset.scrollDay)?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelectorAll('.day-chip').forEach(x=>x.classList.toggle('is-active',x===b))})});document.querySelectorAll('[data-anime-tab]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>showAnimeTab(b.dataset.animeTab))});const f=document.querySelector('#impressionForm');if(f&&!f.dataset.bound){f.dataset.bound='1';f.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(f);try{await api(`/api/anime/${state._anime.id}/impressions`,{method:'POST',body:JSON.stringify({body:fd.get('body'),spoiler:fd.get('spoiler')==='on'})});f.reset();toast('Impressão publicada.');loadImpressions(state._anime.id)}catch{toast('Não foi possível publicar.','error')}})}injectIcons(document)}

async function renderRoute(){clearInterval(state.scheduleTimer);state.scheduleTimer=null;const path=location.pathname.replace(/\/+$/,'')||'/';updateNav(path);app.setAttribute('aria-busy','true');try{if(path==='/')await renderHome();else if(path==='/animes/programacao')await renderSchedule();else if(path==='/animes/catalogo')await renderCatalog();else if(path==='/animes/temporadas')await renderSeasons();else if(path==='/animes/onde-assistir')await renderStreaming();else if(path==='/animes/dublados')await renderDubbed();else if(path==='/animes/estudios')await renderStudios();else if(path==='/listas-de-animes')await renderListsIndex();else if(['/melhores-animes-para-assistir','/animes-mais-assistidos','/animes-mais-aguardados'].includes(path))await renderRanking(path.slice(1));else if(path.startsWith('/anime/'))await renderAnime(path);else if(path==='/perfil')await renderProfile();else if(['/quem-somos','/colabore','/termos-de-uso','/politica-de-privacidade'].includes(path))renderStatic(path);else if(path==='/contato')renderContact();else if(path==='/dmca')renderDmca();else renderNotFound();bindDynamic()}finally{app.setAttribute('aria-busy','false');track('page_view')}}

setTheme(state.theme);document.querySelector('#year').textContent=new Date().getFullYear();injectIcons(document);
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(!a)return;const x=a.dataset.action;if(x==='search')openSearch();if(x==='search-close')closeSearch();if(x==='theme')setTheme(state.theme==='dark'?'light':'dark');if(x==='login')openAuth('login');if(x==='register')openAuth('register');if(x==='auth-close')closeAuth();if(x==='mobile-menu')document.querySelector('#mobileDrawer').hidden=false;if(x==='mobile-menu-close')document.querySelector('#mobileDrawer').hidden=true;if(x==='logout'){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.user=null;state.list.clear();renderAuthHeader();toast('Você saiu da conta.');renderRoute()}if(x==='fav-filter'){state._favOnly=!state._favOnly;a.classList.toggle('is-active',state._favOnly);drawSchedule(nextDays())}if(x==='stream-filter'){state._streamOnly=!state._streamOnly;a.classList.toggle('is-active',state._streamOnly);drawSchedule(nextDays())}if(x==='copy-url'){navigator.clipboard?.writeText(location.href).then(()=>toast('Link copiado.'))}});
document.querySelector('#globalSearch').addEventListener('input',e=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>searchGlobal(e.target.value),280)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeSearch();closeAuth();document.querySelector('#mobileDrawer').hidden=true}});
window.addEventListener('popstate',renderRoute);
window.addEventListener('online',()=>{if(location.pathname==='/animes/programacao')renderSchedule()});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
loadMe().finally(renderRoute);
})();
